#!/bin/sh
# ✅ [td-graph] shared law runner of the staged batches: law <expected "P/F"> <repo-relative file>; runs from <root> (ROOT) with bare env (no Nx namespace), a short artifact dir inside the checkout (as the suite runner's checkout scratch) and the pinned runtime via the root bunfig; sets FAILED=1 on a mismatch
: "${ROOT:?}"; FAILED=0; ART="$ROOT/.cache/test-sandbox/tgv"; mkdir -p "$ART"
law() { want="$1"; f="$2"; out=$(cd "$ROOT" && env -u SEMIO_NX_FIXED_STORAGE -u NX_CACHE_DIRECTORY -u SEMIO_SCRIPT_PROCESS_INVOCATION SEMIO_TEST_ARTIFACT_DIR="$ART" nice -n 10 bun test --timeout 170000 "./$f" 2>&1); got="$(printf '%s\n' "$out" | grep -E '^ *[0-9]+ pass$' | tr -dc 0-9)/$(printf '%s\n' "$out" | grep -E '^ *[0-9]+ fail$' | tr -dc 0-9)"; if [ "$got" = "$want" ]; then echo "OK    $got $f"; else echo "FAIL  got $got want $want $f"; printf '%s\n' "$out" | grep -E '^\(fail\)' | cut -c1-200; FAILED=1; fi; }
# envlaw <expected "P/F"> <repo-relative file>: the same file inside the official script process envelope (ver-f proc-run rewritten to ROOT, runner kept outside ROOT)
envlaw() { want="$1"; f="$2"; C="$(cd "$(dirname "$0")/../../.." && pwd)"; run="$C/🗑️generated/td-graph/run/proc-run-$(printf %s "$ROOT" | cksum | cut -d' ' -f1).ts"; mkdir -p "$(dirname "$run")"; sed "s#/Users/ueli/Documents/semio#$ROOT#g" "$C/ver-f-tools/proc-run.ts" > "$run"; out=$(cd "$ROOT" && env -u SEMIO_NX_FIXED_STORAGE -u NX_CACHE_DIRECTORY VF_WALL=300 bun "$run" file "$ROOT/$f" 2>&1); got="$(printf '%s\n' "$out" | grep -E '^ *[0-9]+ pass$' | tr -dc 0-9)/$(printf '%s\n' "$out" | grep -E '^ *[0-9]+ fail$' | tr -dc 0-9)"; if [ "$got" = "$want" ]; then echo "OK    $got (envelope) $f"; else echo "FAIL  got $got want $want (envelope) $f"; printf '%s\n' "$out" | grep -E '^\(fail\)' | cut -c1-200; FAILED=1; fi; }
